import type { TextareaProps } from "./textarea.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Textarea";

// Generate child element class names for the component, should match available style slots
export const TextareaClasses = {
  root: "exp-textura_textarea",
  input: "exp-textura_textarea_input",
  characterCount: "exp-textura_textarea_character_count",
  characterCountWarning: "exp-textura_textarea_character_count_warning",
  sm: "exp-textura_textarea_sm",
  resizeHorizontal: "exp-textura_textarea_resize_horizontal",
  resizeVertical: "exp-textura_textarea_resize_vertical",
  resizeNone: "exp-textura_textarea_resize_none",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    hover: {
      color: theme.inputTextarea.critical.color.content.filled.hover,
      border: `${theme.toRem(theme.inputTextarea.border.width)} solid ${theme.inputTextarea.critical.color.border.hover}`,
      "&::placeholder": {
        color: theme.inputTextarea.critical.color.content.placeholder.hover,
      },
    },
    active: {
      color: theme.inputTextarea.critical.color.content.filled.pressed,
      "&::placeholder": {
        color: theme.inputTextarea.critical.color.content.placeholder.pressed,
      },
    },
    disabled: {
      border: `${theme.toRem(theme.inputTextarea.border.width)} solid ${theme.inputTextarea.critical.color.border.disabled}`,
      color: theme.inputTextarea.critical.color.content.filled.disabled,
      "&::placeholder": {
        color: theme.inputTextarea.critical.color.content.placeholder.disabled,
      },
    },
    input: {
      border: `${theme.toRem(theme.inputTextarea.border.width)} solid ${theme.inputTextarea.critical.color.border.enabled}`,
      color: theme.inputTextarea.critical.color.content.filled.enabled,
    },
    placeholder: {
      color: theme.inputTextarea.critical.color.content.placeholder.enabled,
    },
    prefix: {
      color: theme.inputTextarea.critical.color.content.placeholder.enabled,
    },
    suffix: {
      color: theme.inputTextarea.critical.color.content.placeholder.enabled,
    },
  },
});

const generateStyles = (props: TextareaProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<TextareaProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "block",
    backgroundColor: "transparent",
    width: "100%",

    [`.${TextareaClasses.input}`]: {
      width: "100%",
      backgroundColor: "transparent",
      border: `${theme.toRem(theme.inputTextarea.border.width)} solid ${theme.inputTextarea.default.color.border.enabled}`,
      borderRadius: theme.toRem(theme.inputTextarea.border.radius),
      color: theme.inputTextarea.default.color.content.filled.enabled,
      outline: 0,
      margin: 0,
      height: theme.toRem(82),
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[8])} 0 ${theme.toRem(theme.spacing[8])}`,
      ...theme.typography.body.md,

      "&::placeholder": {
        color: theme.inputTextarea.default.color.content.placeholder.enabled,
        ...styleSlots?.placeholder,
      },

      "&:focus-visible": {
        outline: "none",
        borderColor: theme.inputTextarea.default.color.border.pressed,
        borderWidth: theme.toRem(theme.inputTextarea.border.width),
        ...styleSlots?.focus,
      },

      "&:hover": {
        borderColor: theme.inputTextarea.default.color.border.hover,
        color: theme.inputTextarea.default.color.content.filled.hover,
        "&::placeholder": {
          color: theme.inputTextarea.default.color.content.placeholder.hover,
        },
        ...styleSlots?.hover,
      },

      "&:active": {
        borderColor: theme.inputTextarea.default.color.border.pressed,
        borderWidth: theme.toRem(theme.inputTextarea.border.width),
        color: theme.inputTextarea.default.color.content.filled.pressed,
        "&::placeholder": {
          color: theme.inputTextarea.default.color.content.placeholder.pressed,
        },
        ...styleSlots?.active,
      },

      "&[disabled]": {
        background: "transparent",
        borderColor: theme.inputTextarea.default.color.border.disabled,
        color: theme.inputTextarea.default.color.content.filled.disabled,
        boxShadow: "none",
        cursor: "not-allowed",
        "&::placeholder": {
          color: theme.inputTextarea.default.color.content.placeholder.disabled,
        },
        ...styleSlots?.disabled,
      },

      ...styleSlots?.input,
    },

    [`.${TextareaClasses.characterCount}`]: {
      fontSize: theme.typography.fontSize[12],
      marginTop: theme.toRem(theme.spacing[4]),
      textAlign: "end",
      color: theme.color.content.weak,
      ...styleSlots?.characterCount,
    },

    [`.${TextareaClasses.characterCountWarning}`]: {
      color: theme.color.content.utility.critical,
      ...styleSlots?.characterCountWarning,
    },

    [`.${TextareaClasses.sm}`]: {
      height: theme.toRem(72),
      ...theme.typography.body.sm,
    },

    [`.${TextareaClasses.resizeHorizontal}`]: {
      resize: "horizontal",
    },

    [`.${TextareaClasses.resizeVertical}`]: {
      resize: "vertical",
    },

    [`.${TextareaClasses.resizeNone}`]: {
      resize: "none",
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledTextarea = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<TextareaProps>((props) => generateStyles(props));
